#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.assign(n, 0);
    if (n == 0) return;

    // Parallel inclusive scan from right to left:
    // output[i] = sum_{k=i}^{n-1} x[k]
    // Implemented as a per-thread local sum + offsets (block-wise scan).

    int nthreads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            nthreads = omp_get_num_threads();
        }
    }

    std::vector<long long> blockSums(nthreads, 0LL);
    std::vector<long long> offsets(nthreads, 0LL);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        // 1D block decomposition (contiguous blocks)
        const int start = (tid * n) / T;
        const int end   = ((tid + 1) * n) / T;

        // Local reverse prefix within the block
        long long local = 0;
        for (int i = end - 1; i >= start; --i) {
            local += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local);
        }

        // Store total sum of this block
        blockSums[tid] = local;

        #pragma omp barrier

        // Compute offset = sum of all blocks strictly to the right of this block.
        // Do this in a single thread to avoid races.
        #pragma omp single
        {
            long long running = 0;
            for (int t = T - 1; t >= 0; --t) {
                offsets[t] = running;
                running += blockSums[t];
            }
        }

        #pragma omp barrier

        // Add offset to all elements in this block
        const long long off = offsets[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + off);
        }
    }
}
